"\"\"\"Fix common issues and run tests.\"\"\"\n\nimport json\nimport subprocess\nimport sys\nfrom pathlib import Path\n\n# 1. Create directories & basic data files\nPath(\"data\").mkdir(exist_ok=True)\nPath(\"data/stock\").mkdir(parents=True, exist_ok=True)\n\nsub_file = Path(\"data/stock/subscriptions.json\")\nif not sub_file.exists():\n    sub_file.write_text(json.dumps([{\n        \"author\": {\"name\": \"示例作者\", \"platform\": \"bilibili\", \"author_id\": \"12345\"},\n        \"subscribed_at\": \"2026-01-01T00:00:00\",\n        \"score\": 0.5, \"total_analyses\": 5,\n        \"last_monitored_at\": \"2026-07-01T00:00:00\",\n        \"tags\": [\"A股\"], \"is_blacklisted\": False, \"id\": \"sub001\",\n    }], ensure_ascii=False, indent=2))\n    print(\"Created subscriptions.json\")\n\nblack_file = Path(\"data/stock/blacklist.json\")\nif not black_file.exists():\n    black_file.write_text(json.dumps([], ensure_ascii=False, indent=2))\n    print(\"Created blacklist.json\")\n\n# 2. Run web tests\nresult = subprocess.run(\n    [sys.executable, \"-m\", \"pytest\", \"tests/test_web_routes.py\", \"-v\", \"--tb=short\"],\n    capture_output=True, text=True,\n)\nprint()\nprint(result.stdout[-2000:] if len(result.stdout) > 2000 else result.stdout)\n\nfailed = result.returncode != 0\nif failed:\n    for line in result.stdout.split(\"\\n\"):\n        if \"FAILED\" in line:\n            print(f\"  ❌ {line.strip()}\")\nelse:\n    print(\"\\n✅ ALL WEB TESTS PASSED\")\n\nsys.exit(result.returncode)"